# -----------------------------------------------------------------------------
# Text decoder
# -----------------------------------------------------------------------------
class Dots3NoteOmniTextRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)


class Dots3NoteOmniTextLayerNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.bias = nn.Parameter(torch.zeros(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        x = hidden_states.to(torch.float32)
        mean = x.mean(-1, keepdim=True)
        var = (x - mean).pow(2).mean(-1, keepdim=True)
        x = (x - mean) * torch.rsqrt(var + self.variance_epsilon)
        return self.weight * x.to(input_dtype) + self.bias


# ---------------------------------------------------------------------------
# Rotary embedding (decoupled RoPE part only, GPT-J / interleaved style)
# ---------------------------------------------------------------------------
class Dots3NoteOmniTextRotaryEmbedding(nn.Module):
    def __init__(self, dim, base=10000.0):
        super().__init__()
        self.dim = dim
        self.base = base
        inv_freq = 1.0 / (base ** (torch.arange(0, dim, 2, dtype=torch.int64).float() / dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, position_ids):
        # position_ids: [B, S] -> cos/sin: [B, S, dim/2]
        inv_freq = self.inv_freq.to(x.device)
        pos = position_ids[:, :, None].float() * inv_freq[None, None, :]
        return pos.cos().to(x.dtype), pos.sin().to(x.dtype)


class Dots3NoteOmniTextIndexerLayerNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.hidden_size = hidden_size
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(hidden_size, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(hidden_size, dtype=torch.float32))

    def forward(self, hidden_states):
        return F.layer_norm(
            hidden_states.float(),
            (self.hidden_size,),
            self.weight.float(),
            self.bias.float(),
            self.eps,
        ).to(hidden_states.dtype)


class Dots3NoteOmniTextDynamicIndexedLayer(DynamicIndexedLayer):
    """Dynamic DSA cache layer with a companion per-token FP8 scale cache."""

    def __init__(self):
        super().__init__()
        self.indexer_scales = None

    def update_indexer_fp8(self, indexer_keys, indexer_scales):
        indexer_keys = super().update_indexer(indexer_keys)
        if self.indexer_scales is None:
            self.indexer_scales = torch.empty(
                (*indexer_scales.shape[:1], 0, *indexer_scales.shape[2:]),
                dtype=indexer_scales.dtype,
                device=indexer_scales.device,
            )
        self.indexer_scales = torch.cat((self.indexer_scales, indexer_scales), dim=1)
        return indexer_keys, self.indexer_scales

    def offload(self):
        super().offload()
        if self.indexer_scales is not None:
            self.indexer_scales = self.indexer_scales.to("cpu", non_blocking=True)

    def prefetch(self):
        super().prefetch()
        if self.indexer_scales is not None and self.indexer_scales.device != self.device:
            self.indexer_scales = self.indexer_scales.to(self.device, non_blocking=True)

    def reset(self):
        super().reset()
        if self.indexer_scales is not None:
            self.indexer_scales.zero_()

    def reorder_cache(self, beam_idx):
        super().reorder_cache(beam_idx)
        if self.indexer_scales is not None and self.indexer_scales.numel() > 0:
            self.indexer_scales = self.indexer_scales.index_select(0, beam_idx.to(self.indexer_scales.device))

    def crop(self, tokens_to_remove):
        super().crop(tokens_to_remove)
        if self.indexer_scales is not None and self.indexer_scales.numel() > 0:
            self.indexer_scales = self.indexer_scales[:, : self.indexer_keys.shape[1], :]

    def batch_repeat_interleave(self, repeats):
        super().batch_repeat_interleave(repeats)
        if self.indexer_scales is not None and self.indexer_scales.numel() > 0:
            self.indexer_scales = self.indexer_scales.repeat_interleave(repeats, dim=0)

    def batch_select_indices(self, indices):
        super().batch_select_indices(indices)
        if self.indexer_scales is not None and self.indexer_scales.numel() > 0:
            self.indexer_scales = self.indexer_scales[indices, ...]


class Dots3NoteOmniTextDynamicCache(DynamicCache):
    """Hybrid DSA/SWA cache with FP8 index-key storage on DSA layers."""

    def __init__(self, config):
        layers = [
            DynamicSlidingWindowLayer(sliding_window=config.sliding_window)
            if layer_type == "sliding_attention"
            else Dots3NoteOmniTextDynamicIndexedLayer()
            for layer_type in config.layer_types
        ]
        Cache.__init__(self, layers=layers)

    def update_indexer_fp8(self, indexer_keys, indexer_scales, layer_idx):
        layer = self.layers[layer_idx]
        if not isinstance(layer, Dots3NoteOmniTextDynamicIndexedLayer):
            raise ValueError(f"Layer {layer_idx} is not configured as a DSA cache layer")
        return layer.update_indexer_fp8(indexer_keys, indexer_scales)


def apply_rotary_interleaved(x, cos, sin):
    """Apply GPT-J-style interleaved rotary embeddings.

    x:   [B, H, S, dim]
    cos: [B, S, dim/2]
    sin: [B, S, dim/2]
    """
    cos = cos.unsqueeze(1)  # [B, 1, S, dim/2]
    sin = sin.unsqueeze(1)
    even = x[..., 0::2]
    odd = x[..., 1::2]
    out_even = even * cos - odd * sin
    out_odd = odd * cos + even * sin
    out = torch.stack((out_even, out_odd), dim=-1)
    return out.flatten(-2)


# ---------------------------------------------------------------------------
# Dynamic sparse attention indexer
# ---------------------------------------------------------------------------
def normalized_hadamard_transform(x):
    """Reference normalized Walsh-Hadamard transform over the last dimension."""
    hidden_size = x.shape[-1]
    if hidden_size < 1 or hidden_size & (hidden_size - 1):
        raise ValueError("The DSA index_head_dim must be a positive power of two")

    original_shape = x.shape
    output = x.float().reshape(-1, hidden_size)
    block_size = 1
    while block_size < hidden_size:
        output = output.reshape(-1, hidden_size // (block_size * 2), 2, block_size)
        left, right = output.unbind(dim=-2)
        output = torch.cat((left + right, left - right), dim=-1).reshape(-1, hidden_size)
        block_size *= 2
    return (output.reshape(original_shape) * hidden_size**-0.5).to(x.dtype)


def quantize_indexer_fp8(x):
    """Apply the per-token FP8 E4M3 quantization used by the checkpoint indexer."""
    block_size = 128
    if x.shape[-1] % block_size:
        raise ValueError("index_head_dim must be divisible by the FP8 indexer block size (128)")

    blocks = x.float().reshape(*x.shape[:-1], -1, block_size)
    scale = blocks.abs().amax(dim=-1, keepdim=True).clamp_min(1e-4) / 448.0
    scale = torch.pow(2.0, torch.ceil(torch.log2(scale)))
    quantized = (blocks / scale).clamp(-448.0, 448.0).to(torch.float8_e4m3fn)
    return quantized.reshape_as(x), scale.squeeze(-1)


def _normalize_cache_position(cache_position, query_length, key_length, device):
    """Return physical cache columns for each query as a `[B, Q]` tensor."""
    if cache_position is None:
        cache_position = torch.arange(key_length - query_length, key_length, device=device)
    else:
        cache_position = cache_position.to(device)
    if cache_position.ndim == 0:
        cache_position = cache_position.view(1)
    if cache_position.ndim == 1:
        cache_position = cache_position.unsqueeze(0)
    elif cache_position.ndim != 2:
        raise ValueError(f"cache_position must be 1D or 2D, got shape {tuple(cache_position.shape)}")
    if cache_position.shape[-1] < query_length:
        raise ValueError(f"cache_position has {cache_position.shape[-1]} entries for {query_length} query token(s)")
    return cache_position[:, -query_length:]


class Dots3NoteOmniTextIndexer(nn.Module):
    """Lightning indexer used on the DSA/full-attention layers."""

    def __init__(self, config, layer_idx):
        super().__init__()
        self.layer_idx = layer_idx
        self.n_heads = config.index_n_heads
        self.head_dim = config.index_head_dim
        self.rope_head_dim = config.qk_rope_head_dim
        self.index_topk = config.index_topk
        self.softmax_scale = self.head_dim**-0.5
        self.query_chunk_size = 1024

        self.wq_b = nn.Linear(config.q_lora_rank, self.n_heads * self.head_dim, bias=False)
        self.wk = nn.Linear(config.hidden_size, self.head_dim, bias=False)
        self.k_norm = Dots3NoteOmniTextIndexerLayerNorm(self.head_dim)
        self.weights_proj = nn.Linear(config.hidden_size, self.n_heads, bias=False)

    @torch.no_grad()
    def forward(self, hidden_states, q_lora, cos, sin, padding_mask, cache_position, past_key_values=None):
        batch_size, seq_len, _ = hidden_states.shape
        query = self.wq_b(q_lora).view(batch_size, seq_len, self.n_heads, self.head_dim)
        key = self.k_norm(self.wk(hidden_states)).view(batch_size, seq_len, 1, self.head_dim)

        q_rope, q_nope = torch.split(query, [self.rope_head_dim, self.head_dim - self.rope_head_dim], dim=-1)
        k_rope, k_nope = torch.split(key, [self.rope_head_dim, self.head_dim - self.rope_head_dim], dim=-1)
        q_rope = apply_rotary_interleaved(q_rope.transpose(1, 2), cos, sin).transpose(1, 2)
        k_rope = apply_rotary_interleaved(k_rope.transpose(1, 2), cos, sin).transpose(1, 2)
        query = normalized_hadamard_transform(torch.cat((q_rope, q_nope), dim=-1))
        key = normalized_hadamard_transform(torch.cat((k_rope, k_nope), dim=-1)).squeeze(2)

        query, query_scale = quantize_indexer_fp8(query.contiguous())
        key, key_scale = quantize_indexer_fp8(key.contiguous())

        if past_key_values is not None:
            if hasattr(past_key_values, "update_indexer_fp8"):
                key, key_scale = past_key_values.update_indexer_fp8(key, key_scale, self.layer_idx)
            else:
                dequantized_key = key.float() * key_scale
                dequantized_key = past_key_values.update_indexer(dequantized_key, self.layer_idx)
                key = dequantized_key
                key_scale = None

        weights = self.weights_proj(hidden_states).float() * (self.n_heads**-0.5) * self.softmax_scale
        key_float = key.float()
        key_transposed = key_float.transpose(-1, -2).unsqueeze(1)
        key_positions = torch.arange(key.shape[1], device=hidden_states.device)
        query_cache_positions = _normalize_cache_position(cache_position, seq_len, key.shape[1], hidden_states.device)
        topk = min(self.index_topk, key.shape[1])
        topk_indices = []

        for start in range(0, seq_len, self.query_chunk_size):
            stop = min(start + self.query_chunk_size, seq_len)
            scores = torch.matmul(query[:, start:stop].float(), key_transposed)
            scores = scores * query_scale[:, start:stop]
            if key_scale is not None:
                scores = scores * key_scale[:, None, None, :, 0]
            scores = F.relu(scores)

            index_scores = torch.matmul(weights[:, start:stop].unsqueeze(-2), scores).squeeze(-2)
            causal = key_positions[None, None, :] > query_cache_positions[:, start:stop, None]
            index_scores.masked_fill_(causal, float("-inf"))
            if padding_mask is not None:
                if padding_mask.ndim == 2:
                    padding = padding_mask[:, None, : key.shape[1]].to(torch.bool)
                    index_scores.masked_fill_(~padding, float("-inf"))
                else:
                    index_scores = index_scores + padding_mask[:, start:stop, : key.shape[1]]
            topk_indices.append(index_scores.topk(topk, dim=-1).indices.to(torch.int32))

        return torch.cat(topk_indices, dim=1)


# ---------------------------------------------------------------------------
# Dense MLP
# ---------------------------------------------------------------------------
class Dots3NoteOmniTextMLP(nn.Module):
    def __init__(self, config, intermediate_size=None):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.intermediate_size = intermediate_size if intermediate_size is not None else config.intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        return self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))


# ---------------------------------------------------------------------------
# MoE gate (noaux_tc: sigmoid scores + correction bias)
# ---------------------------------------------------------------------------
class MoEGate(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.top_k = config.num_experts_per_tok
        self.n_routed_experts = config.n_routed_experts
        self.norm_topk_prob = config.norm_topk_prob
        self.scoring_func = config.scoring_func
        self.topk_method = config.topk_method
        self.routed_scaling_factor = config.routed_scaling_factor
        self.gating_fp32 = config.moe_gating_fp32
        self.use_dynamic_rsf = config.use_dynamic_rsf
        self.n_group = config.n_group
        self.topk_group = config.topk_group

        self.weight = nn.Parameter(torch.empty((self.n_routed_experts, config.hidden_size)))
        if self.topk_method == "noaux_tc":
            self.e_score_correction_bias = nn.Parameter(torch.empty((self.n_routed_experts), dtype=torch.float32))
        else:
            self.register_parameter("e_score_correction_bias", None)

    def forward(self, hidden_states):
        # hidden_states: [T, H]
        if self.gating_fp32:
            logits = F.linear(hidden_states.float(), self.weight.float(), None)
        else:
            logits = F.linear(hidden_states, self.weight, None)

        if self.scoring_func == "sigmoid":
            scores = logits.sigmoid().float()
        elif self.scoring_func == "softmax":
            scores = logits.softmax(dim=-1, dtype=torch.float32)
        else:
            raise ValueError(f"Unsupported scoring_func: {self.scoring_func!r}")

        if self.topk_method == "noaux_tc":
            scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)
            scores_per_group = scores_for_choice.view(-1, self.n_group, self.n_routed_experts // self.n_group)
            group_scores = scores_per_group.topk(min(2, scores_per_group.shape[-1]), dim=-1).values.sum(dim=-1)
            group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False).indices
            group_mask = torch.zeros_like(group_scores, dtype=torch.bool)
            group_mask.scatter_(1, group_idx, True)
            score_mask = (
                group_mask.unsqueeze(-1)
                .expand(-1, self.n_group, self.n_routed_experts // self.n_group)
                .reshape(-1, self.n_routed_experts)
            )
            scores_for_choice = scores_for_choice.masked_fill(~score_mask, float("-inf"))
            topk_idx = torch.topk(scores_for_choice, k=self.top_k, dim=-1, sorted=False).indices
            topk_weight = scores.gather(1, topk_idx)
        elif self.topk_method == "greedy":
            topk_weight, topk_idx = torch.topk(scores, k=self.top_k, dim=-1, sorted=False)
        else:
            raise ValueError(f"Unsupported topk_method: {self.topk_method!r}")

        if self.norm_topk_prob:
            topk_weight = topk_weight / (topk_weight.sum(dim=-1, keepdim=True) + 1e-20)
        if self.use_dynamic_rsf:
            routed_scaling_factor = 1.0 / (topk_weight.norm(dim=-1, keepdim=True) + 1e-20)
        else:
            routed_scaling_factor = self.routed_scaling_factor
        topk_weight = topk_weight * routed_scaling_factor

        return topk_idx, topk_weight.to(hidden_states.dtype)


# ---------------------------------------------------------------------------
# Sparse MoE FFN
# ---------------------------------------------------------------------------
@use_experts_implementation
class Dots3NoteOmniTextExperts(nn.Module):
    """Routed expert weights stored in the packed Transformers MoE layout."""

    def __init__(self, config):
        super().__init__()
        self.num_experts = config.n_routed_experts
        self.hidden_dim = config.hidden_size
        self.intermediate_dim = config.moe_intermediate_size
        self.gate_up_proj = nn.Parameter(torch.empty(self.num_experts, 2 * self.intermediate_dim, self.hidden_dim))
        self.down_proj = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim, self.intermediate_dim))
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, hidden_states, top_k_index, top_k_weights):
        final_hidden_states = torch.zeros_like(hidden_states)
        with torch.no_grad():
            expert_mask = torch.nn.functional.one_hot(top_k_index, num_classes=self.num_experts).permute(2, 1, 0)
            expert_hit = torch.greater(expert_mask.sum(dim=(-1, -2)), 0).nonzero(as_tuple=False).view(-1)

        for expert_idx in expert_hit:
            top_k_pos, token_idx = torch.where(expert_mask[expert_idx])
            current_state = hidden_states[token_idx]
            gate = F.linear(current_state, self.gate_up_proj[expert_idx, : self.intermediate_dim])
            up = F.linear(current_state, self.gate_up_proj[expert_idx, self.intermediate_dim :])
            current_hidden_states = self.act_fn(gate) * up
            current_hidden_states = F.linear(current_hidden_states, self.down_proj[expert_idx])
            current_hidden_states = current_hidden_states * top_k_weights[token_idx, top_k_pos, None]
            final_hidden_states.index_add_(0, token_idx, current_hidden_states.to(final_hidden_states.dtype))

        return final_hidden_states


class Dots3NoteOmniTextMoE(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.num_experts = config.n_routed_experts
        self.top_k = config.num_experts_per_tok
        self.experts = Dots3NoteOmniTextExperts(config)
        self.gate = MoEGate(config)
        if config.n_shared_experts is not None and config.n_shared_experts > 0:
            shared_inter = config.shared_experts_intermediate_size * config.n_shared_experts
            self.shared_experts = Dots3NoteOmniTextMLP(config, intermediate_size=shared_inter)
        else:
            self.shared_experts = None

    def forward(self, hidden_states):
        orig_shape = hidden_states.shape
        hidden_states = hidden_states.view(-1, orig_shape[-1])
        topk_idx, topk_weight = self.gate(hidden_states)

        final = self.experts(hidden_states, topk_idx, topk_weight)

        if self.shared_experts is not None:
            final = final + self.shared_experts(hidden_states)

        return final.view(*orig_shape)


def _get_norm(dim, eps, normalization_type):
    if normalization_type == "LayerNorm":
        return Dots3NoteOmniTextLayerNorm(dim, eps=eps)
    return Dots3NoteOmniTextRMSNorm(dim, eps=eps)


# ---------------------------------------------------------------------------
# MLA attention
# ---------------------------------------------------------------------------
def eager_attention_forward(module, query, key, value, attention_mask, scaling, dropout=0.0, **kwargs):
    attn_weights = torch.matmul(query, key.transpose(2, 3)) * scaling
    fully_masked = None
    if attention_mask is not None:
        attention_mask = attention_mask[:, :, :, : key.shape[-2]]
        if attention_mask.dtype == torch.bool:
            fully_masked = ~attention_mask.any(dim=-1, keepdim=True)
            attn_weights = attn_weights.masked_fill(~attention_mask, torch.finfo(attn_weights.dtype).min)
        else:
            fully_masked = attention_mask.amax(dim=-1, keepdim=True) < 0
            attn_weights = attn_weights + attention_mask
    attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    if fully_masked is not None:
        attn_weights = attn_weights.masked_fill(fully_masked, 0)
    attn_weights = F.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value)
    return attn_output.transpose(1, 2).contiguous(), attn_weights


def dsa_sparse_attention_forward(
    query,
    key,
    value,
    topk_indices,
    cache_position,
    padding_mask,
    scaling,
    query_chunk_size=512,
    head_chunk_size=32,
):
    """Reference DSA fallback that computes attention only over indexer-selected tokens."""
    batch_size, num_heads, query_length, _ = query.shape
    output = value.new_empty(batch_size, num_heads, query_length, value.shape[-1])
    batch_indices = torch.arange(batch_size, device=query.device)[:, None, None, None]
    query_cache_positions = _normalize_cache_position(cache_position, query_length, key.shape[2], query.device)

    for query_start in range(0, query_length, query_chunk_size):
        query_stop = min(query_start + query_chunk_size, query_length)
        token_indices = topk_indices[:, query_start:query_stop].long()
        valid = token_indices <= query_cache_positions[:, query_start:query_stop, None]
        if padding_mask is not None:
            selected_padding = padding_mask[:, : key.shape[2]].to(torch.bool).gather(1, token_indices.flatten(1))
            valid = valid & selected_padding.view_as(token_indices)

        for head_start in range(0, num_heads, head_chunk_size):
            head_stop = min(head_start + head_chunk_size, num_heads)
            head_indices = torch.arange(head_start, head_stop, device=query.device)[None, :, None, None]
            selected_key = key[batch_indices, head_indices, token_indices[:, None], :]
            scores = torch.einsum(
                "bhqd,bhqkd->bhqk",
                query[:, head_start:head_stop, query_start:query_stop],
                selected_key,
            ).float()
            scores.mul_(scaling).masked_fill_(~valid[:, None], torch.finfo(scores.dtype).min)
            probabilities = F.softmax(scores, dim=-1).to(query.dtype)
            selected_value = value[batch_indices, head_indices, token_indices[:, None], :]
            output[:, head_start:head_stop, query_start:query_stop] = torch.einsum(
                "bhqk,bhqkd->bhqd", probabilities, selected_value
            )

    return output.transpose(1, 2).contiguous(), None


class Dots3NoteOmniTextAttention(nn.Module):
    def __init__(self, config: Dots3NoteOmniConfig, layer_idx: int, is_sliding: bool = False):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.hidden_size = config.hidden_size

        # The sliding-window layers use a different MLA shape than the full layers.
        if is_sliding:
            self.num_heads = config.swa_num_attention_heads
            self.num_key_value_heads = config.swa_num_key_value_heads
            self.q_lora_rank = config.swa_q_lora_rank
            self.kv_lora_rank = config.swa_kv_lora_rank
            self.qk_nope_head_dim = config.swa_qk_nope_head_dim
            self.qk_rope_head_dim = config.swa_qk_rope_head_dim
            self.v_head_dim = config.swa_v_head_dim
            self.rope_theta = config.swa_rope_theta
            self.head_dim = config.swa_head_dim
            attention_gate_type = config.swa_attention_gate_type
        else:
            self.num_heads = config.num_attention_heads
            self.num_key_value_heads = config.num_key_value_heads
            self.q_lora_rank = config.q_lora_rank
            self.kv_lora_rank = config.kv_lora_rank
            self.qk_nope_head_dim = config.qk_nope_head_dim
            self.qk_rope_head_dim = config.qk_rope_head_dim
            self.v_head_dim = config.v_head_dim
            self.rope_theta = config.rope_theta
            self.head_dim = config.head_dim
            attention_gate_type = config.attention_gate_type

        self.qk_head_dim = self.qk_nope_head_dim + self.qk_rope_head_dim
        if is_sliding and self.head_dim != self.qk_head_dim:
            raise ValueError(
                f"SWA head_dim ({self.head_dim}) must equal qk_nope_head_dim + qk_rope_head_dim ({self.qk_head_dim})."
            )

        self.apply_lora_scale = config.apply_mla_qkv_lora_rescale
        self.scaling = self.qk_head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True

        self.is_sliding = is_sliding
        self.use_dsa = config.use_dsa and not is_sliding
        self.sliding_window = config.sliding_window if is_sliding else None

        norm_type = config.normalization

        # q low-rank
        if self.q_lora_rank is not None:
            self.q_a_proj = nn.Linear(self.hidden_size, self.q_lora_rank, bias=config.attention_bias)
            self.q_a_layernorm = _get_norm(self.q_lora_rank, config.rms_norm_eps, norm_type)
            self.q_b_proj = nn.Linear(self.q_lora_rank, self.num_heads * self.qk_head_dim, bias=config.attention_bias)
        else:
            self.q_proj = nn.Linear(self.hidden_size, self.num_heads * self.qk_head_dim, bias=config.attention_bias)

        # kv low-rank (compressed latent + decoupled rope key)
        self.kv_a_proj_with_mqa = nn.Linear(
            self.hidden_size, self.kv_lora_rank + self.qk_rope_head_dim, bias=config.attention_bias
        )
        self.kv_a_layernorm = _get_norm(self.kv_lora_rank, config.rms_norm_eps, norm_type)
        self.kv_b_proj = nn.Linear(
            self.kv_lora_rank,
            self.num_heads * (self.qk_nope_head_dim + self.v_head_dim),
            bias=config.attention_bias,
        )

        if config.k_rope_only_layernorm:
            self.k_rope_only_layernorm = _get_norm(self.qk_rope_head_dim, config.rms_norm_eps, norm_type)
        else:
            self.k_rope_only_layernorm = None

        # output sigmoid gate
        self.attention_gate_type = attention_gate_type
        if self.attention_gate_type == "elementwise":
            self.g_proj = nn.Linear(self.hidden_size, self.num_heads * self.v_head_dim, bias=config.attention_bias)
        elif self.attention_gate_type == "headwise":
            self.g_proj = nn.Linear(self.hidden_size, self.num_heads, bias=config.attention_bias)
        else:
            self.g_proj = None

        self.o_proj = nn.Linear(self.num_heads * self.v_head_dim, self.hidden_size, bias=config.attention_bias)
        if self.use_dsa:
            if self.q_lora_rank is None:
                raise ValueError("DSA requires q_lora_rank to construct the indexer query")
            self.indexer = Dots3NoteOmniTextIndexer(config, layer_idx)

    def forward(
        self,
        hidden_states,
        cos,
        sin,
        position_ids,
        attention_mask=None,
        padding_mask=None,
        past_key_value=None,
        cache_position=None,
        output_attentions=False,
    ):
        bsz, q_len, _ = hidden_states.size()

        # ---- query ----
        q_lora = None
        if self.q_lora_rank is not None:
            q_lora = self.q_a_proj(hidden_states)
            q_lora = self.q_a_layernorm(q_lora)
            if self.apply_lora_scale:
                q_lora = q_lora * (self.hidden_size / self.q_lora_rank) ** 0.5
            q = self.q_b_proj(q_lora)
        else:
            q = self.q_proj(hidden_states)
        q = q.view(bsz, q_len, self.num_heads, self.qk_head_dim).transpose(1, 2)
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        # ---- compressed kv ----
        latent = self.kv_a_proj_with_mqa(hidden_states)
        kv_a, k_pe = torch.split(latent, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1)
        kv_a = self.kv_a_layernorm(kv_a.contiguous())
        if self.apply_lora_scale:
            kv_a = kv_a * (self.hidden_size / self.kv_lora_rank) ** 0.5
        kv = self.kv_b_proj(kv_a)
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim).transpose(1, 2)
        k_nope, value_states = torch.split(kv, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        # decoupled rope key: single (mqa) head, shared across heads
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim).transpose(1, 2)  # [B,1,S,rope]
        if self.k_rope_only_layernorm is not None:
            k_pe = self.k_rope_only_layernorm(k_pe)

        q_pe = apply_rotary_interleaved(q_pe, cos, sin)
        k_pe = apply_rotary_interleaved(k_pe, cos, sin)

        query_states = torch.cat([q_nope, q_pe], dim=-1)  # [B,H,S,qk_head_dim]
        k_pe = k_pe.expand(bsz, self.num_heads, q_len, self.qk_rope_head_dim)
        key_states = torch.cat([k_nope, k_pe], dim=-1)  # [B,H,S,qk_head_dim]

        if past_key_value is not None:
            cache_kwargs = {"cache_position": cache_position}
            key_states, value_states = past_key_value.update(key_states, value_states, self.layer_idx, cache_kwargs)

        if attention_mask is not None and attention_mask.shape[-1] != key_states.shape[-2]:
            attention_mask = attention_mask[..., -key_states.shape[-2] :]

        if self.use_dsa:
            topk_indices = self.indexer(
                hidden_states,
                q_lora,
                cos,
                sin,
                padding_mask,
                cache_position,
                past_key_values=past_key_value,
            )

            if not output_attentions and key_states.shape[-2] > topk_indices.shape[-1] * 2:
                attn_output, attn_weights = dsa_sparse_attention_forward(
                    query_states,
                    key_states,
                    value_states,
                    topk_indices,
                    cache_position,
                    padding_mask,
                    self.scaling,
                )
                attention_backend = None
            else:
                attention_backend = self.config._attn_implementation

            if attention_backend is not None:
                index_mask = (
                    topk_indices.new_ones((bsz, q_len, key_states.shape[-2]), dtype=torch.bool)
                    .scatter(-1, topk_indices.long(), False)
                    .unsqueeze(1)
                )
                key_positions = torch.arange(key_states.shape[-2], device=hidden_states.device)
                query_cache_positions = _normalize_cache_position(
                    cache_position, q_len, key_states.shape[-2], hidden_states.device
                )
                index_mask |= key_positions[None, None, None, :] > query_cache_positions[:, None, :, None]
                if padding_mask is not None:
                    index_mask |= ~padding_mask[:, None, None, : key_states.shape[-2]].to(torch.bool)
                if attention_mask is None:
                    attention_mask = ~index_mask
                elif attention_mask.dtype == torch.bool:
                    attention_mask = attention_mask & ~index_mask
                else:
                    attention_mask = attention_mask.masked_fill(index_mask, torch.finfo(hidden_states.dtype).min)
        else:
            attention_backend = self.config._attn_implementation

        if attention_backend is not None:
            attention_interface = eager_attention_forward
            if not output_attentions and attention_backend != "eager":
                if hasattr(ALL_ATTENTION_FUNCTIONS, "get_interface"):
                    attention_interface = ALL_ATTENTION_FUNCTIONS.get_interface(
                        attention_backend, eager_attention_forward
                    )
                else:
                    attention_interface = ALL_ATTENTION_FUNCTIONS[attention_backend]

            attn_output, attn_weights = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask,
                dropout=self.attention_dropout if self.training else 0.0,
                scaling=self.scaling,
                sliding_window=self.sliding_window,
                is_causal=attention_mask is None,
                output_attentions=output_attentions,
            )

        # ---- output sigmoid gate ----
        if self.g_proj is not None:
            g = self.g_proj(hidden_states)  # [B,S,H] (headwise) or [B,S,H*v] (elementwise)
            if self.attention_gate_type == "elementwise":
                g = g.view(bsz, q_len, self.num_heads, self.v_head_dim)
                attn_output = attn_output * torch.sigmoid(g)
            else:  # headwise
                attn_output = attn_output * torch.sigmoid(g).unsqueeze(-1)

        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights if output_attentions else None


# ---------------------------------------------------------------------------
# Decoder layer
# ---------------------------------------------------------------------------
def _is_sparse_layer(config, layer_idx):
    moe_layer_freq = config.moe_layer_freq
    first_k_dense_replace = config.first_k_dense_replace
    if layer_idx < first_k_dense_replace:
        return False
    if isinstance(moe_layer_freq, (list, tuple)):
        return bool(moe_layer_freq[layer_idx])
    if isinstance(moe_layer_freq, int):
        return (layer_idx - first_k_dense_replace) % moe_layer_freq == 0
    return True


class Dots3NoteOmniTextDecoderLayer(nn.Module):
    def __init__(self, config: Dots3NoteOmniConfig, layer_idx: int):
        super().__init__()
        self.layer_idx = layer_idx
        layer_types = config.layer_types
        is_sliding = (
            config.use_sliding_window
            and layer_types is not None
            and layer_idx < len(layer_types)
            and layer_types[layer_idx] == "sliding_attention"
        )
        self.is_sliding = is_sliding
        self.self_attn = Dots3NoteOmniTextAttention(config, layer_idx, is_sliding=is_sliding)

        if _is_sparse_layer(config, layer_idx):
            self.mlp = Dots3NoteOmniTextMoE(config)
        else:
            self.mlp = Dots3NoteOmniTextMLP(config)

        self.input_layernorm = _get_norm(config.hidden_size, config.rms_norm_eps, config.normalization)
        self.post_attention_layernorm = _get_norm(config.hidden_size, config.rms_norm_eps, config.normalization)

    def forward(
        self,
        hidden_states,
        cos,
        sin,
        position_ids,
        attention_mask=None,
        padding_mask=None,
        past_key_value=None,
        cache_position=None,
        output_attentions=False,
    ):
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states, self_attn_weights = self.self_attn(
            hidden_states,
            cos,
            sin,
            position_ids,
            attention_mask=attention_mask,
            padding_mask=padding_mask,
            past_key_value=past_key_value,
            cache_position=cache_position,
            output_attentions=output_attentions,
        )
        hidden_states = residual + hidden_states

        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states
        outputs = (hidden_states,)
        if output_attentions:
            outputs += (self_attn_weights,)
        return outputs


# ---------------------------------------------------------------------------
# Pretrained base
# ---------------------------------------------------------------------------
class Dots3NoteOmniPreTrainedModel(PreTrainedModel):
    config_class = Dots3NoteOmniConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["Dots3NoteOmniTextDecoderLayer"]
    _skip_keys_device_placement = ["past_key_values"]
    _supports_cache_class = True
    _supports_sdpa = True
    _supports_flash_attn = False
    _supports_attention_backend = True
    _keep_in_fp32_modules_strict = ["e_score_correction_bias"]
    _keys_to_ignore_on_load_unexpected = [r"^model\.layers\.46\.", r"^model\.mtp\."]

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, Dots3NoteOmniTextRotaryEmbedding):
            inv_freq = 1.0 / (
                module.base
                ** (
                    torch.arange(
                        0,
                        module.dim,
                        2,
                        dtype=torch.float32,
                        device=module.inv_freq.device,
                    )
                    / module.dim
                )
            )
            init.copy_(module.inv_freq, inv_freq)
        elif isinstance(module, MoEGate):
            init.normal_(module.weight, mean=0.0, std=self.config.initializer_range)
            if module.e_score_correction_bias is not None:
                init.zeros_(module.e_score_correction_bias)
        elif isinstance(module, Dots3NoteOmniTextExperts):
            init.normal_(module.gate_up_proj, mean=0.0, std=self.config.initializer_range)
            init.normal_(module.down_proj, mean=0.0, std=self.config.initializer_range)


# ---------------------------------------------------------------------------
# Base model
# ---------------------------------------------------------------------------
class Dots3NoteOmniTextModel(Dots3NoteOmniPreTrainedModel):
    def __init__(self, config: Dots3NoteOmniConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size
        self.num_hidden_layers = config.num_hidden_layers

        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, self.padding_idx)

        self.layers = nn.ModuleList(
            [Dots3NoteOmniTextDecoderLayer(config, i) for i in range(config.num_hidden_layers)]
        )

        self.norm = _get_norm(config.hidden_size, config.rms_norm_eps, config.final_norm)
        self.rotary_emb = Dots3NoteOmniTextRotaryEmbedding(config.qk_rope_head_dim, base=config.rope_theta)
        self.swa_rotary_emb = Dots3NoteOmniTextRotaryEmbedding(config.swa_qk_rope_head_dim, base=config.swa_rope_theta)

        self.gradient_checkpointing = False
        self.post_init()

    def get_input_embeddings(self):
        return self.embed_tokens

    def set_input_embeddings(self, value):
        self.embed_tokens = value

    def _make_masks(self, attention_mask, inputs_embeds, past_key_values, position_ids):
        """Return backend-specific masks without eagerly constructing additive square tensors."""
        if isinstance(attention_mask, dict):
            return attention_mask["full_attention"], attention_mask["sliding_attention"]

        mask_kwargs = {
            "config": self.config,
            "inputs_embeds": inputs_embeds,
            "attention_mask": attention_mask,
            "past_key_values": past_key_values,
            "position_ids": position_ids,
        }
        full_mask = create_causal_mask(**mask_kwargs)
        sliding_mask = (
            create_sliding_window_causal_mask(**mask_kwargs) if self.config.use_sliding_window else full_mask
        )
        return full_mask, sliding_mask

    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        use_cache: bool | None = None,
        output_attentions: bool | None = None,
        output_hidden_states: bool | None = None,
        return_dict: bool | None = None,
        **kwargs,
    ) -> tuple | BaseModelOutputWithPast:
        use_cache = use_cache if use_cache is not None else self.config.use_cache
        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        return_dict = return_dict if return_dict is not None else self.config.return_dict
        cache_position = kwargs.pop("cache_position", None)

        if (input_ids is None) == (inputs_embeds is None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        bsz, q_len = inputs_embeds.shape[:2]

        if self.gradient_checkpointing and self.training and use_cache:
            logger.warning_once("`use_cache=True` is incompatible with gradient checkpointing. Disabling cache.")
            use_cache = False

        if use_cache and past_key_values is None:
            past_key_values = Dots3NoteOmniTextDynamicCache(self.config)

        past_len = past_key_values.get_seq_length() if past_key_values is not None else 0
        if cache_position is None:
            cache_position = torch.arange(past_len, past_len + q_len, device=inputs_embeds.device)
        if position_ids is None:
            position_ids = cache_position.unsqueeze(0).expand(bsz, -1)

        cos, sin = self.rotary_emb(inputs_embeds, position_ids)
        swa_cos, swa_sin = self.swa_rotary_emb(inputs_embeds, position_ids)

        padding_mask = (
            attention_mask if isinstance(attention_mask, torch.Tensor) and attention_mask.ndim == 2 else None
        )
        full_mask, sliding_mask = self._make_masks(attention_mask, inputs_embeds, past_key_values, position_ids)

        hidden_states = inputs_embeds
        all_hidden_states = () if output_hidden_states else None
        all_self_attentions = () if output_attentions else None

        for idx in range(self.num_hidden_layers):
            layer = self.layers[idx]
            if output_hidden_states:
                all_hidden_states += (hidden_states,)
            layer_mask = sliding_mask if layer.is_sliding else full_mask
            layer_cos, layer_sin = (swa_cos, swa_sin) if layer.is_sliding else (cos, sin)
            if self.gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    layer.__call__,
                    hidden_states,
                    layer_cos,
                    layer_sin,
                    position_ids,
                    layer_mask,
                    padding_mask,
                    past_key_values,
                    cache_position,
                    output_attentions,
                )
            else:
                layer_outputs = layer(
                    hidden_states,
                    layer_cos,
                    layer_sin,
                    position_ids,
                    attention_mask=layer_mask,
                    padding_mask=padding_mask,
                    past_key_value=past_key_values,
                    cache_position=cache_position,
                    output_attentions=output_attentions,
                )
            hidden_states = layer_outputs[0]
            if output_attentions:
                all_self_attentions += (layer_outputs[1],)

        hidden_states = self.norm(hidden_states)
        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        if not return_dict:
            return tuple(
                value
                for value in (hidden_states, past_key_values, all_hidden_states, all_self_attentions)
                if value is not None
            )
        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values if use_cache else None,
            hidden_states=all_hidden_states,
            attentions=all_self_attentions,
        )


# ---------------------------------------------------------------------------
# Causal LM head
# ---------------------------------------------------------------------------
class Dots3NoteOmniTextForCausalLM(Dots3NoteOmniPreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.embed_tokens.weight"}

    @classmethod
    def _supports_default_dynamic_cache(cls):
        # Let Dots3NoteOmniTextModel create Dots3NoteOmniTextDynamicCache so the DSA index keys
        # remain FP8 during the standard generate() path.
        return False

    def __init__(self, config: Dots3NoteOmniConfig):
        super().__init__(config)
        self.model = Dots3NoteOmniTextModel(config)
        self.vocab_size = config.vocab_size
        self.lm_head = nn.Linear(config.hidden_size, config.vocab_size, bias=False)
        self.post_init()

    def get_input_embeddings(self):
        return self.model.embed_tokens

    def set_input_embeddings(self, value):
        self.model.embed_tokens = value

    def get_output_embeddings(self):
        return self.lm_head

    def set_output_embeddings(self, new_embeddings):
        self.lm_head = new_embeddings

    def get_decoder(self):
        return self.model

    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        labels: torch.LongTensor | None = None,
        use_cache: bool | None = None,
        output_attentions: bool | None = None,
        output_hidden_states: bool | None = None,
        return_dict: bool | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        **kwargs,
    ) -> tuple | CausalLMOutputWithPast:
        return_dict = return_dict if return_dict is not None else self.config.return_dict
        cache_position = kwargs.pop("cache_position", None)

        outputs = self.model(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            use_cache=use_cache,
            output_attentions=output_attentions,
            output_hidden_states=output_hidden_states,
            return_dict=True,
            cache_position=cache_position,
        )
        hidden_states = outputs.last_hidden_state

        slice_indices = (
            slice(None)
            if labels is not None
            else (slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep)
        )
        logits = self.lm_head(hidden_states[:, slice_indices, :])

        loss = None
        if labels is not None:
            logits = logits.float()
            shift_logits = logits[..., :-1, :].contiguous()
            shift_labels = labels[..., 1:].contiguous()
            loss = F.cross_entropy(
                shift_logits.view(-1, self.config.vocab_size),
                shift_labels.view(-1).to(shift_logits.device),
                ignore_index=-100,
            )

        if not return_dict:
            output = tuple(
                value
                for value in (logits, outputs.past_key_values, outputs.hidden_states, outputs.attentions)
                if value is not None
            )
            return (loss,) + output if loss is not None else output

        return CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
        )


# -----------------------------------------------------------------------------
# Audio encoder and adapter
# -----------------------------------------------------------------------------
class Dots3NoteOmniAudioRMSNorm(nn.Module):
    def __init__(self, hidden_size: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.eps = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        variance = hidden_states.pow(2).mean(dim=-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.eps)
        return self.weight * hidden_states


class Dots3NoteOmniAudioRotaryEmbedding(nn.Module):
    def __init__(self, head_dim: int, partial_rotary_factor: float, rope_theta: float):
        super().__init__()
        self.rotary_dim = (int(head_dim * partial_rotary_factor) // 2) * 2
        self.rope_theta = float(rope_theta)
        self.register_buffer("inv_freq", self._make_inv_freq(), persistent=False)

    def _make_inv_freq(self, device: torch.device | None = None) -> torch.Tensor:
        if self.rotary_dim == 0:
            return torch.empty(0, dtype=torch.float32, device=device)
        positions = torch.arange(0, self.rotary_dim, 2, dtype=torch.float32, device=device)
        return 1.0 / (self.rope_theta ** (positions / self.rotary_dim))

    @torch.no_grad()
    def forward(
        self,
        position_ids: torch.Tensor,
        dtype: torch.dtype,
    ) -> tuple[torch.Tensor | None, torch.Tensor | None]:
        if self.rotary_dim == 0:
            return None, None
        if self.inv_freq.dtype != torch.float32:
            inv_freq = self._make_inv_freq(device=position_ids.device)
        else:
            inv_freq = self.inv_freq.to(device=position_ids.device)
        device_type = position_ids.device.type
        with torch.autocast(device_type=device_type, enabled=False):
            inv_freq_expanded = inv_freq[None, :, None]
            position_ids_expanded = position_ids[:, None, :].float()
            frequencies = (inv_freq_expanded.float() @ position_ids_expanded.float()).transpose(1, 2)
            embedding = torch.cat((frequencies, frequencies), dim=-1)
            return embedding.cos().to(dtype), embedding.sin().to(dtype)


def _rotate_half(hidden_states: torch.Tensor) -> torch.Tensor:
    first, second = hidden_states.chunk(2, dim=-1)
    return torch.cat((-second, first), dim=-1)


def _apply_rotary(
    query: torch.Tensor,
    key: torch.Tensor,
    cosine: torch.Tensor | None,
    sine: torch.Tensor | None,
) -> tuple[torch.Tensor, torch.Tensor]:
    if cosine is None or sine is None:
        return query, key
    rotary_dim = cosine.shape[-1]
    if query.ndim == 4:
        cosine = cosine[:, None, :, :]
        sine = sine[:, None, :, :]
    else:
        cosine = cosine[:, None, :]
        sine = sine[:, None, :]
    query_rot, query_pass = query[..., :rotary_dim], query[..., rotary_dim:]
    key_rot, key_pass = key[..., :rotary_dim], key[..., rotary_dim:]
    query_rot = query_rot * cosine + _rotate_half(query_rot) * sine
    key_rot = key_rot * cosine + _rotate_half(key_rot) * sine
    return torch.cat((query_rot, query_pass), dim=-1), torch.cat((key_rot, key_pass), dim=-1)


class Dots3NoteOmniAudioAttention(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        attention_dropout: float,
        backend: str,
    ):
        super().__init__()
        if hidden_size % num_heads:
            raise ValueError("audio hidden_size must be divisible by num_heads")
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim = hidden_size // num_heads
        self.attention_dropout = attention_dropout
        self.backend = backend
        self.scaling = self.head_dim**-0.5
        self.k_proj = nn.Linear(hidden_size, hidden_size, bias=False)
        self.v_proj = nn.Linear(hidden_size, hidden_size, bias=True)
        self.q_proj = nn.Linear(hidden_size, hidden_size, bias=True)
        self.out_proj = nn.Linear(hidden_size, hidden_size, bias=True)

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None,
        cosine: torch.Tensor | None,
        sine: torch.Tensor | None,
        cumulative_lengths: torch.Tensor | None = None,
        max_sequence_length: int | None = None,
    ) -> torch.Tensor:
        if hidden_states.ndim == 2:
            if self.backend != "flash_attention_2":
                raise ValueError("flattened audio attention requires the FlashAttention backend")
            if cumulative_lengths is None or max_sequence_length is None:
                raise ValueError("flattened audio attention requires sequence metadata")
            query = self.q_proj(hidden_states).view(-1, self.num_heads, self.head_dim)
            key = self.k_proj(hidden_states).view(-1, self.num_heads, self.head_dim)
            value = self.v_proj(hidden_states).view(-1, self.num_heads, self.head_dim)
            query, key = _apply_rotary(query, key, cosine, sine)
            output = self._flash_attention_flat(
                query,
                key,
                value,
                cumulative_lengths,
                max_sequence_length,
            )
            return self.out_proj(output.view(-1, self.hidden_size))

        batch_size, sequence_length, _ = hidden_states.shape

        def project(layer: nn.Linear) -> torch.Tensor:
            projected = layer(hidden_states)
            return projected.view(batch_size, sequence_length, self.num_heads, self.head_dim).transpose(1, 2)

        query, key, value = project(self.q_proj), project(self.k_proj), project(self.v_proj)
        query, key = _apply_rotary(query, key, cosine, sine)
        if self.backend == "flash_attention_2":
            output = self._flash_attention(query, key, value, attention_mask)
        else:
            sdpa_mask = None if attention_mask is None else attention_mask[:, None, None, :]
            output = F.scaled_dot_product_attention(
                query,
                key,
                value,
                attn_mask=sdpa_mask,
                dropout_p=self.attention_dropout if self.training else 0.0,
                is_causal=False,
            )
        output = output.transpose(1, 2).contiguous().view(batch_size, sequence_length, self.hidden_size)
        return self.out_proj(output)

    def _flash_attention_flat(
        self,
        query: torch.Tensor,
        key: torch.Tensor,
        value: torch.Tensor,
        cumulative_lengths: torch.Tensor,
        max_sequence_length: int,
    ) -> torch.Tensor:
        try:
            from flash_attn_interface import flash_attn_varlen_func as fa3_varlen_func
        except ImportError:
            fa3_varlen_func = None
        if fa3_varlen_func is not None:
            return fa3_varlen_func(
                q=query,
                k=key,
                v=value,
                cu_seqlens_q=cumulative_lengths,
                cu_seqlens_k=cumulative_lengths,
                max_seqlen_q=max_sequence_length,
                max_seqlen_k=max_sequence_length,
                softmax_scale=self.scaling,
                causal=False,
                return_attn_probs=True,
            )[0]
        try:
            from flash_attn import flash_attn_varlen_func
        except ImportError as error:
            raise ImportError(
                "attention_backend='flash_attention_2' requires the optional flash-attn package"
            ) from error
        return flash_attn_varlen_func(
            query,
            key,
            value,
            cu_seqlens_q=cumulative_lengths,
            cu_seqlens_k=cumulative_lengths,
            max_seqlen_q=max_sequence_length,
            max_seqlen_k=max_sequence_length,
            dropout_p=self.attention_dropout if self.training else 0.0,
            softmax_scale=self.scaling,
            causal=False,
        )

    def _flash_attention(
        self,
        query: torch.Tensor,
        key: torch.Tensor,
        value: torch.Tensor,
        attention_mask: torch.Tensor | None,
    ) -> torch.Tensor:
        try:
            from flash_attn import flash_attn_func, flash_attn_varlen_func
        except ImportError as error:
            raise ImportError(
                "attention_backend='flash_attention_2' requires the optional flash-attn package"
            ) from error

        query = query.transpose(1, 2)
        key = key.transpose(1, 2)
        value = value.transpose(1, 2)
        if attention_mask is None:
            output = flash_attn_func(
                query,
                key,
                value,
                dropout_p=self.attention_dropout if self.training else 0.0,
                softmax_scale=self.scaling,
                causal=False,
            )
        else:
            sequence_lengths = attention_mask.sum(dim=-1, dtype=torch.int32)
            cumulative_lengths = F.pad(
                sequence_lengths.cumsum(dim=0, dtype=torch.int32),
                (1, 0),
            )
            query_flat = query[attention_mask]
            key_flat = key[attention_mask]
            value_flat = value[attention_mask]
            max_sequence_length = int(sequence_lengths.max().item())
            try:
                from flash_attn_interface import flash_attn_varlen_func as fa3_varlen_func
            except ImportError:
                fa3_varlen_func = None
            if fa3_varlen_func is not None:
                output_flat = fa3_varlen_func(
                    q=query_flat,
                    k=key_flat,
                    v=value_flat,
                    cu_seqlens_q=cumulative_lengths,
                    cu_seqlens_k=cumulative_lengths,
                    max_seqlen_q=max_sequence_length,
                    max_seqlen_k=max_sequence_length,
                    softmax_scale=self.scaling,
                    causal=False,
                    return_attn_probs=True,
                )[0]
            else:
                output_flat = flash_attn_varlen_func(
                    query_flat,
                    key_flat,
                    value_flat,
                    cu_seqlens_q=cumulative_lengths,
                    cu_seqlens_k=cumulative_lengths,
                    max_seqlen_q=max_sequence_length,
                    max_seqlen_k=max_sequence_length,
                    dropout_p=self.attention_dropout if self.training else 0.0,
                    softmax_scale=self.scaling,
                    causal=False,
                )
            output = torch.zeros_like(query)
            output[attention_mask] = output_flat
        return output.transpose(1, 2)


class Dots3NoteOmniAudioEncoderLayer(nn.Module):
    def __init__(self, config: Dots3NoteOmniAudioConfig):
        super().__init__()
        encoder = config.whisper_config
        hidden_size = int(encoder["d_model"])
        ffn_size = int(encoder["encoder_ffn_dim"])
        norm_class = Dots3NoteOmniAudioRMSNorm if config.use_rms_norm else nn.LayerNorm
        self.self_attn = Dots3NoteOmniAudioAttention(
            hidden_size,
            int(encoder["encoder_attention_heads"]),
            float(encoder.get("attention_dropout", 0.0)),
            config.attention_backend,
        )
        self.self_attn_layer_norm = norm_class(hidden_size)
        self.fc1 = nn.Linear(hidden_size, ffn_size * 2)
        self.fc2 = nn.Linear(ffn_size, hidden_size)
        self.final_layer_norm = norm_class(hidden_size)
        self.dropout = float(encoder.get("dropout", 0.0))
        self.activation_dropout = float(encoder.get("activation_dropout", 0.0))

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None,
        cosine: torch.Tensor | None,
        sine: torch.Tensor | None,
        cumulative_lengths: torch.Tensor | None = None,
        max_sequence_length: int | None = None,
    ) -> torch.Tensor:
        residual = hidden_states
        hidden_states = self.self_attn_layer_norm(hidden_states)
        hidden_states = self.self_attn(
            hidden_states,
            attention_mask,
            cosine,
            sine,
            cumulative_lengths,
            max_sequence_length,
        )
        hidden_states = residual + F.dropout(hidden_states, p=self.dropout, training=self.training)

        residual = hidden_states
        hidden_states = self.final_layer_norm(hidden_states)
        gate, value = self.fc1(hidden_states).chunk(2, dim=-1)
        hidden_states = F.silu(gate) * value
        hidden_states = F.dropout(hidden_states, p=self.activation_dropout, training=self.training)
        hidden_states = self.fc2(hidden_states)
        return residual + F.dropout(hidden_states, p=self.dropout, training=self.training)


class Dots3NoteOmniSpeechEncoder(nn.Module):
    def __init__(self, config: Dots3NoteOmniAudioConfig):
        super().__init__()
        encoder = config.whisper_config
        hidden_size = int(encoder["d_model"])
        downsample_size = config.downsample_hidden_size
        conv_padding = (1, 0) if config.use_causal else 1
        self.use_causal = config.use_causal
        self.conv2d1 = nn.Conv2d(1, downsample_size, 3, stride=2, padding=conv_padding)
        self.conv2d2 = nn.Conv2d(downsample_size, downsample_size, 3, stride=2, padding=conv_padding)
        self.conv2d3 = nn.Conv2d(downsample_size, downsample_size, 3, stride=2, padding=conv_padding)
        frequency_bins = config.feature_size
        for _ in range(3):
            frequency_bins = (frequency_bins + 1) // 2
        self.conv_out = nn.Linear(downsample_size * frequency_bins, hidden_size, bias=False)
        self.rotary_embedding = Dots3NoteOmniAudioRotaryEmbedding(
            hidden_size // int(encoder["encoder_attention_heads"]),
            float(config.rope_parameters.get("partial_rotary_factor", 1.0)),
            float(config.rope_parameters.get("rope_theta", 10_000.0)),
        )
        self.layers = nn.ModuleList(
            [Dots3NoteOmniAudioEncoderLayer(config) for _ in range(int(encoder["encoder_layers"]))]
        )
        norm_class = Dots3NoteOmniAudioRMSNorm if config.use_rms_norm else nn.LayerNorm
        self.layer_norm = norm_class(hidden_size)
        self.dropout = float(encoder.get("dropout", 0.0))
        self.hop_length = config.hop_length
        self.conv_temporal_stride = config.conv_temporal_stride
        self.conv_bucket_step = config.conv_bucket_step
        self.conv_bucket_max_elements = config.conv_bucket_max_elements
        self.attention_backend = config.attention_backend

    @staticmethod
    def _temporal_mask(hidden_states: torch.Tensor, valid_lengths: torch.Tensor) -> torch.Tensor:
        positions = torch.arange(hidden_states.shape[-1], device=hidden_states.device)
        return positions[None, :] < valid_lengths[:, None]

    def _mask_time(self, hidden_states: torch.Tensor, valid_lengths: torch.Tensor) -> torch.Tensor:
        return hidden_states * self._temporal_mask(hidden_states, valid_lengths)[:, None, None, :]

    def _conv_layers(
        self,
        hidden_states: torch.Tensor,
        valid_lengths: torch.Tensor,
    ) -> torch.Tensor:
        if self.use_causal:
            hidden_states = F.pad(hidden_states, (14, 0))
            valid_lengths = valid_lengths + 14
        hidden_states = self._mask_time(hidden_states, valid_lengths)
        hidden_states = F.gelu(self.conv2d1(hidden_states))
        valid_lengths = (valid_lengths + 1) // 2
        hidden_states = self._mask_time(hidden_states, valid_lengths)
        hidden_states = F.gelu(self.conv2d2(hidden_states))
        valid_lengths = (valid_lengths + 1) // 2
        hidden_states = self._mask_time(hidden_states, valid_lengths)
        hidden_states = F.gelu(self.conv2d3(hidden_states))
        valid_lengths = (valid_lengths + 1) // 2
        hidden_states = self._mask_time(hidden_states, valid_lengths)
        return hidden_states

    def _project_conv_output(self, hidden_states: torch.Tensor) -> torch.Tensor:
        batch_size, channels, frequencies, frames = hidden_states.shape
        hidden_states = hidden_states.permute(0, 3, 1, 2).reshape(batch_size, frames, channels * frequencies)
        return self.conv_out(hidden_states)

    def _conv_stem(
        self,
        input_features: torch.Tensor,
        audio_sample_lengths: torch.Tensor,
        input_seq_lens: torch.Tensor,
    ) -> torch.Tensor:
        hidden_states = input_features.unsqueeze(1)
        valid_lengths = audio_sample_lengths.to(hidden_states.device) // self.hop_length
        if self.conv_bucket_step is None:
            return self._project_conv_output(self._conv_layers(hidden_states, valid_lengths))

        step_frames = int(self.conv_bucket_step * 100)
        boundaries = list(range(step_frames, hidden_states.shape[-1], step_frames))
        if not boundaries or boundaries[-1] < hidden_states.shape[-1]:
            boundaries.append(hidden_states.shape[-1])
        groups: dict[int, list[int]] = {}
        for index, sequence_length in enumerate(input_seq_lens.tolist()):
            actual_mel_frames = sequence_length * self.conv_temporal_stride
            bucket_frames = next(boundary for boundary in boundaries if actual_mel_frames <= boundary)
            groups.setdefault(bucket_frames, []).append(index)

        output = hidden_states.new_zeros(
            hidden_states.shape[0],
            int(input_seq_lens.max().item()),
            self.conv_out.out_features,
        )
        for bucket_frames, indexes in sorted(groups.items()):
            index_tensor = torch.tensor(indexes, device=hidden_states.device)
            bucket = hidden_states[index_tensor, :, :, :bucket_frames]
            bucket_valid_lengths = valid_lengths[index_tensor]
            max_elements = self.conv_bucket_max_elements or bucket_frames * len(indexes)
            sub_batch_size = max(1, max_elements // bucket_frames)
            bucket_outputs = []
            for start in range(0, bucket.shape[0], sub_batch_size):
                bucket_outputs.append(
                    self._conv_layers(
                        bucket[start : start + sub_batch_size],
                        bucket_valid_lengths[start : start + sub_batch_size],
                    )
                )
            projected = self._project_conv_output(torch.cat(bucket_outputs, dim=0))
            for local_index, global_index in enumerate(indexes):
                valid_length = int(input_seq_lens[global_index].item())
                output[global_index, :valid_length] = projected[local_index, :valid_length]
        return output

    def forward(
        self,
        input_features: torch.Tensor,
        input_seq_lens: torch.Tensor,
        audio_sample_lens: torch.Tensor,
        return_dict: bool = True,
    ) -> BaseModelOutput | tuple[torch.Tensor]:
        hidden_states = self._conv_stem(input_features, audio_sample_lens, input_seq_lens)
        max_valid_length = int(input_seq_lens.max().item())
        hidden_states = hidden_states[:, :max_valid_length]
        positions = torch.arange(max_valid_length, device=hidden_states.device)[None, :]
        cosine, sine = self.rotary_embedding(positions, hidden_states.dtype)
        hidden_states = F.dropout(hidden_states, p=self.dropout, training=self.training)
        if self.attention_backend == "flash_attention_2":
            sequence_lengths = input_seq_lens.to(device=hidden_states.device, dtype=torch.int32)
            cumulative_lengths = torch.zeros(
                sequence_lengths.shape[0] + 1,
                dtype=torch.int32,
                device=hidden_states.device,
            )
            cumulative_lengths[1:] = sequence_lengths.cumsum(dim=0, dtype=torch.int32)
            hidden_states = torch.cat(
                [hidden_states[index, : int(length.item())] for index, length in enumerate(sequence_lengths)],
                dim=0,
            )
            cosine = torch.cat(
                [cosine[:, : int(length.item())] for length in sequence_lengths],
                dim=1,
            ).squeeze(0)
            sine = torch.cat(
                [sine[:, : int(length.item())] for length in sequence_lengths],
                dim=1,
            ).squeeze(0)
            for layer in self.layers:
                hidden_states = layer(
                    hidden_states,
                    None,
                    cosine,
                    sine,
                    cumulative_lengths,
                    max_valid_length,
                )
            hidden_states = self.layer_norm(hidden_states)
            hidden_states = pad_sequence(
                torch.split(hidden_states, sequence_lengths.cpu().tolist(), dim=0),
                batch_first=True,
            )
        else:
            positions = positions.expand(hidden_states.shape[0], -1)
            attention_mask = positions < input_seq_lens[:, None]
            cosine = cosine.expand(hidden_states.shape[0], -1, -1)
            sine = sine.expand(hidden_states.shape[0], -1, -1)
            for layer in self.layers:
                hidden_states = layer(hidden_states, attention_mask, cosine, sine)
            hidden_states = self.layer_norm(hidden_states)
        if not return_dict:
            return (hidden_states,)
        return BaseModelOutput(last_hidden_state=hidden_states)


class Dots3NoteOmniAudioEncoder(nn.Module):
    def __init__(self, config: Dots3NoteOmniAudioConfig):
        super().__init__()
        self.speech_encoder = Dots3NoteOmniSpeechEncoder(config)


class Dots3NoteOmniAudioAdapter(nn.Module):
    def __init__(self, input_size: int, output_size: int):
        super().__init__()
        self.proj = nn.Sequential(
            nn.LayerNorm(input_size),
            nn.Linear(input_size, output_size),
            nn.GELU(),
            nn.Linear(output_size, output_size),
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        return self.proj(hidden_states)


@dataclass
class Dots3NoteOmniAudioOutput(ModelOutput):
    audio_embeds: torch.Tensor | None = None
    audio_token_lengths: torch.Tensor | None = None


class Dots3NoteOmniAudioPreTrainedModel(PreTrainedModel):
    config_class = Dots3NoteOmniAudioConfig
    base_model_prefix = "audio_encoder"
    main_input_name = "input_features"
    _no_split_modules = ["Dots3NoteOmniAudioEncoderLayer"]
    _supports_sdpa = True

    @torch.no_grad()
    def _init_weights(self, module: nn.Module) -> None:
        super()._init_weights(module)
        if isinstance(module, Dots3NoteOmniAudioRotaryEmbedding):
            inv_freq = module._make_inv_freq(device=module.inv_freq.device)
            init.copy_(module.inv_freq, inv_freq)


class Dots3NoteOmniAudioModel(Dots3NoteOmniAudioPreTrainedModel):
    """Audio tower with checkpoint-compatible module names."""

    def __init__(self, config: Dots3NoteOmniAudioConfig):
        super().__init__(config)
        if config.merge_factor != 1:
            raise ValueError("the current Dots3-Note AE release requires merge_factor=1")
        self.audio_adapter = Dots3NoteOmniAudioAdapter(
            config.adapter_input_size,
            config.adapter_output_size,
        )
        self.dots_encoder = Dots3NoteOmniAudioEncoder(config)
        self.post_init()

    def forward(
        self,
        input_features: torch.Tensor,
        chunk_sample_lengths: torch.Tensor,
        chunk_token_lengths: torch.Tensor,
        audio_chunk_counts: torch.Tensor,
        return_dict: bool = True,
        **kwargs,
    ) -> Dots3NoteOmniAudioOutput | tuple[torch.Tensor, torch.Tensor]:
        encoder_output = self.dots_encoder.speech_encoder(
            input_features=input_features,
            input_seq_lens=chunk_token_lengths,
            audio_sample_lens=chunk_sample_lengths,
            return_dict=True,
        ).last_hidden_state

        chunks = [encoder_output[index, : int(length.item())] for index, length in enumerate(chunk_token_lengths)]
        audio_embeddings = []
        token_lengths = []
        chunk_offset = 0
        for chunk_count in audio_chunk_counts.tolist():
            embedding = torch.cat(chunks[chunk_offset : chunk_offset + chunk_count], dim=0)
            embedding = self.audio_adapter(embedding)
            audio_embeddings.append(embedding)
            token_lengths.append(embedding.shape[0])
            chunk_offset += chunk_count
        if chunk_offset != len(chunks):
            raise ValueError("audio_chunk_counts does not account for every feature chunk")

        embeddings = torch.cat(audio_embeddings, dim=0)
        lengths = torch.tensor(token_lengths, dtype=torch.long, device=embeddings.device)
        if not return_dict:
            return embeddings, lengths
        return Dots3NoteOmniAudioOutput(audio_embeds=embeddings, audio_token_lengths=lengths)


# -----------------------------------------------------------------------------
# Vision encoder and adapter
# -----------------------------------------------------------------------------
class Dots3NoteOmniVisionRMSNorm(nn.Module):
    def __init__(self, hidden_size: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.float()
        variance = hidden_states.square().mean(dim=-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)


class Dots3NoteOmniVisionRotaryEmbedding(nn.Module):
    def __init__(self, dim: int, theta: float = 10_000.0):
        super().__init__()
        self.dim = dim
        self.theta = theta
        inv_freq = 1.0 / (theta ** (torch.arange(0, dim, 2, dtype=torch.float32) / dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def forward(self, position_ids: torch.Tensor) -> torch.Tensor:
        return (position_ids.unsqueeze(-1) * self.inv_freq).flatten(1)


class Dots3NoteOmniVisionPatchEmbed(nn.Module):
    def __init__(self, config: Dots3NoteOmniVisionConfig):
        super().__init__()
        self.num_channels = config.num_channels
        self.temporal_patch_size = config.temporal_patch_size
        self.patch_size = config.patch_size
        self.embed_dim = config.embed_dim
        if self.temporal_patch_size == 1:
            self.proj = nn.Conv2d(
                self.num_channels,
                self.embed_dim,
                kernel_size=self.patch_size,
                stride=self.patch_size,
            )
        else:
            kernel_size = (self.temporal_patch_size, self.patch_size, self.patch_size)
            self.proj = nn.Conv3d(
                self.num_channels,
                self.embed_dim,
                kernel_size=kernel_size,
                stride=kernel_size,
            )
        self.norm = Dots3NoteOmniVisionRMSNorm(self.embed_dim, eps=config.rms_norm_eps)

    def forward(self, pixel_values: torch.Tensor) -> torch.Tensor:
        pixel_values = pixel_values.reshape(
            -1,
            self.num_channels,
            self.temporal_patch_size,
            self.patch_size,
            self.patch_size,
        )
        if self.temporal_patch_size == 1:
            pixel_values = pixel_values.squeeze(2)
        hidden_states = self.proj(pixel_values.to(self.proj.weight.dtype)).reshape(-1, self.embed_dim)
        return self.norm(hidden_states)


class Dots3NoteOmniVisionMLP(nn.Module):
    def __init__(self, config: Dots3NoteOmniVisionConfig, intermediate_size: int | None = None):
        super().__init__()
        intermediate_size = intermediate_size or config.intermediate_size
        self.fc1 = nn.Linear(config.embed_dim, intermediate_size, bias=config.use_bias)
        self.fc2 = nn.Linear(intermediate_size, config.embed_dim, bias=config.use_bias)
        self.fc3 = nn.Linear(config.embed_dim, intermediate_size, bias=config.use_bias)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        return self.fc2(F.silu(self.fc1(hidden_states)) * self.fc3(hidden_states))


class Dots3NoteOmniVisionMoE(nn.Module):
    def __init__(self, config: Dots3NoteOmniVisionConfig, layer_idx: int):
        super().__init__()
        self.num_experts = config.pyramid_num_routed[layer_idx]
        self.top_k = min(int(config.capacity_factor), self.num_experts)
        self.router_scoring_func = config.router_scoring_func
        self.router_scale = config.router_scale
        self.experts = nn.ModuleList(
            [
                Dots3NoteOmniVisionMLP(config, intermediate_size=config.moe_intermediate_size)
                for _ in range(self.num_experts)
            ]
        )
        self.gate_weight = nn.Parameter(torch.empty(self.num_experts, config.embed_dim, dtype=torch.float32))
        self.register_buffer("router_bias", torch.zeros(self.num_experts, dtype=torch.float32))

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        shape = hidden_states.shape
        hidden_states = hidden_states.reshape(-1, shape[-1])
        router_logits = F.linear(hidden_states.float(), self.gate_weight)
        if self.router_scoring_func == "softmax":
            router_probs = router_logits.softmax(dim=-1, dtype=torch.float32).to(hidden_states.dtype)
        else:
            router_probs = router_logits.sigmoid().to(hidden_states.dtype)

        _, selected_experts = torch.topk(
            router_probs + self.router_bias.unsqueeze(0), self.top_k, dim=-1, sorted=False
        )
        routing_weights = router_probs.gather(1, selected_experts)
        if self.router_scoring_func == "sigmoid" and self.top_k > 1:
            routing_weights = routing_weights / routing_weights.sum(dim=-1, keepdim=True)
        routing_weights = routing_weights * self.router_scale

        output = torch.zeros_like(hidden_states)
        weight_sum = torch.zeros(hidden_states.shape[0], dtype=hidden_states.dtype, device=hidden_states.device)
        for expert_idx, expert in enumerate(self.experts):
            token_idx, top_idx = torch.where(selected_experts == expert_idx)
            if token_idx.numel() == 0:
                continue
            weights = routing_weights[token_idx, top_idx]
            output[token_idx] += expert(hidden_states[token_idx]) * weights.unsqueeze(-1)
            weight_sum[token_idx] += weights
        output = output / weight_sum.clamp_min(torch.finfo(output.dtype).eps).unsqueeze(-1)
        return output.reshape(shape)


def rotate_half(hidden_states: torch.Tensor) -> torch.Tensor:
    first, second = hidden_states.chunk(2, dim=-1)
    return torch.cat((-second, first), dim=-1)


def apply_rotary_pos_emb_vision(
    query: torch.Tensor,
    key: torch.Tensor,
    cosine: torch.Tensor,
    sine: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    query_dtype, key_dtype = query.dtype, key.dtype
    cosine, sine = cosine.unsqueeze(-2).float(), sine.unsqueeze(-2).float()
    query = query.float() * cosine + rotate_half(query.float()) * sine
    key = key.float() * cosine + rotate_half(key.float()) * sine
    return query.to(query_dtype), key.to(key_dtype)


def dots3_note_omni_vision_eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs,
) -> tuple[torch.Tensor, torch.Tensor]:
    attention_weights = torch.matmul(query, key.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attention_weights = attention_weights + attention_mask
    attention_weights = F.softmax(attention_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attention_weights = F.dropout(attention_weights, p=dropout, training=module.training)
    attention_output = torch.matmul(attention_weights, value).transpose(1, 2).contiguous()
    return attention_output, attention_weights


class Dots3NoteOmniVisionAttention(nn.Module):
    def __init__(self, config: Dots3NoteOmniVisionConfig):
        super().__init__()
        self.config = config
        self.num_heads = config.num_attention_heads
        self.head_dim = config.embed_dim // self.num_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = config.is_causal
        self.qkv = nn.Linear(config.embed_dim, config.embed_dim * 3, bias=config.use_bias)
        self.proj = nn.Linear(config.embed_dim, config.embed_dim, bias=config.use_bias)
        if config.use_qk_norm:
            self.q_norm = Dots3NoteOmniVisionRMSNorm(self.head_dim, eps=config.rms_norm_eps)
            self.k_norm = Dots3NoteOmniVisionRMSNorm(self.head_dim, eps=config.rms_norm_eps)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        max_seqlen: int | None = None,
        **kwargs,
    ) -> torch.Tensor:
        seq_length = hidden_states.shape[0]
        query, key, value = (
            self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, self.head_dim).permute(1, 0, 2, 3).unbind(0)
        )
        if self.config.use_qk_norm:
            query, key = self.q_norm(query), self.k_norm(key)
        query, key = apply_rotary_pos_emb_vision(query, key, *position_embeddings)
        query = query.transpose(0, 1).unsqueeze(0)
        key = key.transpose(0, 1).unsqueeze(0)
        value = value.transpose(0, 1).unsqueeze(0)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, dots3_note_omni_vision_eager_attention_forward
        )
        if is_flash_attention_requested(self.config):
            max_seqlen = get_max_seqlen(cu_seqlens, self.config, kwargs={"max_seqlen": max_seqlen})
            attention_output, _ = attention_interface(
                self,
                query,
                key,
                value,
                attention_mask=None,
                scaling=self.scaling,
                dropout=self.attention_dropout if self.training else 0.0,
                cu_seq_lens_q=cu_seqlens,
                cu_seq_lens_k=cu_seqlens,
                max_length_q=max_seqlen,
                max_length_k=max_seqlen,
                is_causal=False,
                **kwargs,
            )
        else:
            lengths = (cu_seqlens[1:] - cu_seqlens[:-1]).tolist()
            query_chunks, key_chunks, value_chunks = (
                torch.split(states, lengths, dim=2) for states in (query, key, value)
            )
            attention_output = torch.cat(
                [
                    attention_interface(
                        self,
                        query_chunk,
                        key_chunk,
                        value_chunk,
                        attention_mask=None,
                        scaling=self.scaling,
                        dropout=self.attention_dropout if self.training else 0.0,
                        is_causal=False,
                        **kwargs,
                    )[0]
                    for query_chunk, key_chunk, value_chunk in zip(query_chunks, key_chunks, value_chunks)
                ],
                dim=1,
            )
        return self.proj(attention_output.reshape(seq_length, -1).contiguous())


class Dots3NoteOmniVisionBlock(GradientCheckpointingLayer):
    def __init__(self, config: Dots3NoteOmniVisionConfig, layer_idx: int):
        super().__init__()
        self.norm_1 = Dots3NoteOmniVisionRMSNorm(config.embed_dim, eps=config.rms_norm_eps)
        self.attn = Dots3NoteOmniVisionAttention(config)
        self.norm_2 = Dots3NoteOmniVisionRMSNorm(config.embed_dim, eps=config.rms_norm_eps)
        num_experts = config.pyramid_num_routed[layer_idx]
        self.mlp = Dots3NoteOmniVisionMLP(config) if num_experts < 1 else Dots3NoteOmniVisionMoE(config, layer_idx)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        max_seqlen: int | None = None,
        **kwargs,
    ) -> torch.Tensor:
        hidden_states = hidden_states + self.attn(
            self.norm_1(hidden_states),
            cu_seqlens=cu_seqlens,
            position_embeddings=position_embeddings,
            max_seqlen=max_seqlen,
            **kwargs,
        )
        return hidden_states + self.mlp(self.norm_2(hidden_states))


class Dots3NoteOmniVisionAdapter(nn.Module):
    def __init__(self, config: Dots3NoteOmniVisionConfig):
        super().__init__()
        merged_size = config.adapter_in_dim * config.adapter_merge_size**2
        self.ln_q = nn.LayerNorm(config.adapter_in_dim, eps=1e-6)
        self.mlp = nn.Sequential(
            nn.Linear(merged_size, merged_size),
            nn.GELU(),
            nn.Linear(merged_size, config.adapter_out_dim),
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        return self.mlp(self.ln_q(hidden_states).reshape(-1, self.mlp[0].in_features))


class Dots3NoteOmniVisionPreTrainedModel(PreTrainedModel):
    config_class = Dots3NoteOmniVisionConfig
    base_model_prefix = "vision_encoder"
    main_input_name = "pixel_values"
    input_modalities = ("image", "video")
    supports_gradient_checkpointing = True
    _no_split_modules = ["Dots3NoteOmniVisionBlock"]
    _supports_flash_attn = True
    _supports_sdpa = True
    _supports_attention_backend = True

    @torch.no_grad()
    def _init_weights(self, module: nn.Module):
        super()._init_weights(module)
        if isinstance(module, Dots3NoteOmniVisionRotaryEmbedding):
            inv_freq = 1.0 / (
                module.theta
                ** (torch.arange(0, module.dim, 2, device=module.inv_freq.device, dtype=torch.float32) / module.dim)
            )
            init.copy_(module.inv_freq, inv_freq)
        elif isinstance(module, Dots3NoteOmniVisionMoE):
            init.normal_(module.gate_weight, mean=0.0, std=self.config.initializer_range)
            init.zeros_(module.router_bias)


class Dots3NoteOmniVisionModel(Dots3NoteOmniVisionPreTrainedModel):
    def __init__(self, config: Dots3NoteOmniVisionConfig):
        super().__init__(config)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_embed = Dots3NoteOmniVisionPatchEmbed(config)
        head_dim = config.embed_dim // config.num_attention_heads
        self.rotary_pos_emb = Dots3NoteOmniVisionRotaryEmbedding(head_dim // 2)
        self.blocks = nn.ModuleList(
            [Dots3NoteOmniVisionBlock(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.post_trunk_norm = Dots3NoteOmniVisionRMSNorm(config.embed_dim, eps=config.rms_norm_eps)
        self.adapter = Dots3NoteOmniVisionAdapter(config)
        self.gradient_checkpointing = False
        self.post_init()

    def get_dtype(self) -> torch.dtype:
        return self.patch_embed.proj.weight.dtype

    def get_device(self) -> torch.device:
        return self.patch_embed.proj.weight.device

    def forward(
        self,
        pixel_values: torch.Tensor,
        grid_thw: torch.Tensor,
        output_hidden_states: bool = False,
        return_dict: bool = True,
        **kwargs,
    ) -> BaseModelOutputWithPooling | tuple[torch.Tensor, ...]:
        position_ids = get_vision_position_ids(grid_thw, self.spatial_merge_size, kwargs=kwargs)
        cu_seqlens, max_seqlen = get_vision_attention_seqlens(grid_thw, self.config, kwargs=kwargs)
        hidden_states = self.patch_embed(pixel_values)
        rotary_pos_emb = self.rotary_pos_emb(position_ids)
        rotary_pos_emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (rotary_pos_emb.cos(), rotary_pos_emb.sin())

        all_hidden_states = () if output_hidden_states else None
        for block in self.blocks:
            hidden_states = block(
                hidden_states,
                cu_seqlens=cu_seqlens,
                max_seqlen=max_seqlen,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            if output_hidden_states:
                all_hidden_states += (hidden_states,)
        hidden_states = self.post_trunk_norm(hidden_states)
        merged_hidden_states = self.adapter(hidden_states)
        if not return_dict:
            output = (hidden_states, merged_hidden_states)
            return output + ((all_hidden_states,) if output_hidden_states else ())
        return BaseModelOutputWithPooling(
            last_hidden_state=hidden_states,
            pooler_output=merged_hidden_states,
            hidden_states=all_hidden_states,
        )


# -----------------------------------------------------------------------------
# Unified Omni model
# -----------------------------------------------------------------------------
class Dots3NoteOmniForCausalLM(Dots3NoteOmniTextForCausalLM):
    config_class = Dots3NoteOmniConfig
    input_modalities = ("image", "video", "audio", "text")
    _no_split_modules = [
        "Dots3NoteOmniAudioEncoderLayer",
        "Dots3NoteOmniTextDecoderLayer",
        "Dots3NoteOmniVisionBlock",
    ]

    def __init__(self, config: Dots3NoteOmniConfig):
        super().__init__(config)
        self.vision_encoder = Dots3NoteOmniVisionModel(config.vision_config)
        self.audio_encoder = Dots3NoteOmniAudioModel(config.audio_config)

    def get_image_features(
        self,
        pixel_values: torch.Tensor,
        image_grid_thw: torch.Tensor,
        **kwargs,
    ) -> torch.Tensor:
        """Encode image patches and return embeddings in the language-model width."""
        return self.vision_encoder(
            pixel_values.to(dtype=self.vision_encoder.get_dtype()),
            grid_thw=image_grid_thw,
            return_dict=True,
            **kwargs,
        ).pooler_output

    def get_video_features(
        self,
        pixel_values_videos: torch.Tensor,
        video_grid_thw: torch.Tensor,
        **kwargs,
    ) -> torch.Tensor:
        """Encode video patches with the shared vision encoder."""
        return self.vision_encoder(
            pixel_values_videos.to(dtype=self.vision_encoder.get_dtype()),
            grid_thw=video_grid_thw,
            return_dict=True,
            **kwargs,
        ).pooler_output

    def get_audio_features(
        self,
        input_features: torch.Tensor,
        chunk_sample_lengths: torch.Tensor,
        chunk_token_lengths: torch.Tensor,
        audio_chunk_counts: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Encode log-mel chunks and return flattened embeddings and per-audio lengths."""
        parameter = next(self.audio_encoder.parameters())
        output = self.audio_encoder(
            input_features=input_features.to(device=parameter.device, dtype=parameter.dtype),
            chunk_sample_lengths=chunk_sample_lengths.to(parameter.device),
            chunk_token_lengths=chunk_token_lengths.to(parameter.device),
            audio_chunk_counts=audio_chunk_counts.to(parameter.device),
            return_dict=True,
        )
        return output.audio_embeds, output.audio_token_lengths

    @staticmethod
    def _merge_multimodal_embeddings(
        input_ids: torch.Tensor,
        inputs_embeds: torch.Tensor,
        multimodal_embeddings: torch.Tensor,
        token_id: int,
        modality: str,
    ) -> torch.Tensor:
        special_token_mask = input_ids.eq(token_id)
        placeholder_count = int(special_token_mask.sum())
        embedding_count = multimodal_embeddings.shape[0]
        if placeholder_count != embedding_count:
            raise ValueError(
                f"{modality} embedding/token mismatch: found {placeholder_count} placeholder token(s), "
                f"but the encoder produced {embedding_count} embedding(s)"
            )
        special_token_mask = special_token_mask.unsqueeze(-1).expand_as(inputs_embeds)
        multimodal_embeddings = multimodal_embeddings.to(inputs_embeds.device, inputs_embeds.dtype)
        return inputs_embeds.masked_scatter(special_token_mask, multimodal_embeddings)

    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        labels: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        image_grid_thw: torch.Tensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        video_grid_thw: torch.Tensor | None = None,
        input_features: torch.Tensor | None = None,
        chunk_sample_lengths: torch.Tensor | None = None,
        chunk_token_lengths: torch.Tensor | None = None,
        audio_chunk_counts: torch.Tensor | None = None,
        audio_token_lengths: torch.Tensor | None = None,
        chunk_audio_indices: torch.Tensor | None = None,
        **kwargs,
    ) -> CausalLMOutputWithPast | tuple:
        del chunk_audio_indices
        is_prefill = past_key_values is None or past_key_values.get_seq_length() == 0
        has_multimodal_inputs = any(value is not None for value in (pixel_values, pixel_values_videos, input_features))
        if has_multimodal_inputs and is_prefill:
            if input_ids is None or inputs_embeds is not None:
                raise ValueError("multimodal inputs require input_ids and do not accept inputs_embeds")
            inputs_embeds = self.get_input_embeddings()(input_ids)

            if pixel_values is not None:
                if image_grid_thw is None:
                    raise ValueError("image_grid_thw is required when pixel_values is provided")
                image_embeddings = self.get_image_features(pixel_values, image_grid_thw)
                inputs_embeds = self._merge_multimodal_embeddings(
                    input_ids,
                    inputs_embeds,
                    image_embeddings,
                    self.config.image_token_id,
                    "image",
                )

            if pixel_values_videos is not None:
                if video_grid_thw is None:
                    raise ValueError("video_grid_thw is required when pixel_values_videos is provided")
                video_embeddings = self.get_video_features(pixel_values_videos, video_grid_thw)
                inputs_embeds = self._merge_multimodal_embeddings(
                    input_ids,
                    inputs_embeds,
                    video_embeddings,
                    self.config.video_token_id,
                    "video",
                )

            if input_features is not None:
                required_audio_inputs = {
                    "chunk_sample_lengths": chunk_sample_lengths,
                    "chunk_token_lengths": chunk_token_lengths,
                    "audio_chunk_counts": audio_chunk_counts,
                }
                missing = [name for name, value in required_audio_inputs.items() if value is None]
                if missing:
                    raise ValueError(f"missing audio model inputs: {', '.join(missing)}")
                audio_embeddings, tower_token_lengths = self.get_audio_features(
                    input_features,
                    chunk_sample_lengths,
                    chunk_token_lengths,
                    audio_chunk_counts,
                )
                if audio_token_lengths is not None and not torch.equal(
                    audio_token_lengths.cpu(), tower_token_lengths.cpu()
                ):
                    raise ValueError(
                        "processor/audio encoder token lengths differ: "
                        f"{audio_token_lengths.tolist()} != {tower_token_lengths.tolist()}"
                    )
                inputs_embeds = self._merge_multimodal_embeddings(
                    input_ids,
                    inputs_embeds,
                    audio_embeddings,
                    self.config.audio_token_id,
                    "audio",
                )
            input_ids = None

        return super().forward(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            labels=labels,
            **kwargs,
        )


class Dots3NoteOmniForConditionalGeneration(Dots3NoteOmniForCausalLM):
    """Alias following the multimodal generation naming convention."""


